function.arguments:
{"command": "cat << 'DEBUGVIM' > /tmp/debug_test.vim
" Debug test
source /app/plugin/layout_quine.vim
edit /tmp/ta.txt
echo "After edit ta.txt, current bufname: " . bufname('%')
echo "Buffer number of current: " . bufnr('%')
vsplit
echo "After vsplit, num buffers: " . bufnr('$')
edit /tmp/tb.txt
echo "After edit tb.txt, current bufname: " . bufname('%')
echo "winlayout(1): " . winlayout(1)
echo "Testing bufname on leaf buffers..."
for i in range(1, bufnr('$'))
  echo "Buffer " . i . ": " . bufname(i)
endfor
LayoutQuine /tmp/debug_out.vim
echo "Done"
q!
DEBUGVIM

timeout 5 vim -u NONE -N -S /tmp/debug_test.vim 2>&1 || echo "Timed out or error"
echo "---"
cat /tmp/debug_out.vim 2>/dev/null"}

{"command": "cat << 'TESTVIM' > /tmp/test_bufnums.vim
" Test what buffers winlayout refers to
edit /tmp/ta.txt
vsplit  
edit /tmp/tb.txt
echo "bufnr('\$'): " . bufnr('$')
echo "bufname(1): " . bufname(1)
echo "bufname(2): " . bufname(2)
let l:wl = winlayout(1)
echo "winlayout: " . l:wl
if l:wl[0] ==# 'row'
  echo "Left leaf bufnr: " . l:wl[1][0][1]
  echo "Left leaf bufname: " . bufname(l:wl[1][0][1])
  echo "Right leaf bufnr: " . l:wl[1][1][1]
  echo "Right leaf bufname: " . bufname(l:wl[1][1][1])
endif
qa!
TESTVIM
timeout 3 vim -u NONE -N -S /tmp/test_bufnums.vim 2>/dev/null"}
